// Some portions generated by Claude

// Scrolling the Graphs list (the Types list scrolls the same way) with the page: through a list taller than the browser
// can lay out (a million graphs, about 45 million px of rows) and to the end of an ordinary one. Served by the
// Workbench fixture, so no RDF4J server is needed.
const { test, expect } = require('@playwright/test');
const { createServer } = require('./workbench-preview-scroll-fixture.cjs');

const MILLION = 1000000;

let fixture;
let baseUrl;

test.beforeAll(async () => {
	fixture = createServer();
	await new Promise((resolve, reject) => {
		fixture.once('error', reject);
		fixture.listen(0, '127.0.0.1', resolve);
	});
	baseUrl = `http://127.0.0.1:${fixture.address().port}`;
});

test.afterAll(async () => {
	if (fixture && fixture.listening) {
		await new Promise((resolve, reject) => fixture.close(error => error ? reject(error) : resolve()));
	}
});

/** Opens the Graphs page of a repository with count named graphs and waits until all of them are listed. */
async function openGraphs(page, count) {
	await page.setViewportSize({ width: 1280, height: 900 });
	await page.goto(`${baseUrl}/rdf4j-workbench/repositories/a/contexts?fixture-graphs=${count}`);
	const card = page.locator('#contexts-results');
	await expect(card.locator('.workbench-browse-card__count')).toHaveText(/\d/, { timeout: 60000 });
	await expect.poll(() => card.locator('.workbench-browse-card__count')
		.evaluate(element => Number(element.textContent.replace(/\D/g, ''))), { timeout: 60000 }).toBe(count);
	// The counts are asked for once the list is bound; the fixture's never arrive, so each graph shows a dash.
	await expect(card.locator('tr[data-workbench-row-index] .workbench-count-cell').first()).toHaveText('—');
	await page.locator('#contexts-filter').evaluate(field => field.blur());
	await settled(page);
}

/**
 * The graph rows in view, below the context bar: the first one's index with how far it is scrolled out above the
 * bar, the last fully visible one, how many are in view, and whether the default graph row is wholly in view.
 */
function view(page) {
	return page.evaluate(() => {
		const offset = parseFloat(getComputedStyle(document.documentElement)
			.getPropertyValue('--workbench-contextbar-height')) || 0;
		const rows = Array.from(document.querySelectorAll('#contexts-results tr[data-workbench-row-index]'))
			.map(row => ({ index: Number(row.getAttribute('data-workbench-row-index')), box: row.getBoundingClientRect() }));
		const visible = rows.filter(row => row.box.bottom > offset + 1 && row.box.top < innerHeight - 1);
		const whole = visible.filter(row => row.box.top >= offset - 1 && row.box.bottom <= innerHeight + 1);
		const first = visible[0];
		const pitch = rows.length > 1 ? rows[1].box.top - rows[0].box.top : 0;
		const defaultRow = document.querySelector('.workbench-browse-default-row');
		const defaultBox = defaultRow && defaultRow.getBoundingClientRect();
		return {
			position: first ? first.index + (offset - first.box.top) / pitch : null,
			pitch,
			first: first ? first.index : null,
			lastWhole: whole.length ? whole[whole.length - 1].index : null,
			visibleRows: visible.length,
			viewHeight: innerHeight - offset,
			indexes: visible.map(row => row.index),
			defaultInView: !!defaultBox && defaultBox.top >= offset - 1 && defaultBox.bottom <= innerHeight + 1
		};
	});
}

/** Waits until the page has stopped scrolling and the rows in view have stopped changing. */
async function settled(page) {
	let previous = '';
	await expect.poll(async () => {
		const state = await page.evaluate(() => scrollY + ':' + Array.from(document.querySelectorAll(
			'#contexts-results tr[data-workbench-row-index]')).map(row => row.getAttribute('data-workbench-row-index')
			+ '@' + Math.round(row.getBoundingClientRect().top)).join(','));
		const quiet = state === previous;
		previous = state;
		return quiet;
	}, { intervals: [300], timeout: 20000 }).toBe(true);
}

/** Scrolls the page to the middle of the list, where a compressed scroll bar is compressed the most. */
async function toMiddle(page) {
	await page.evaluate(() => window.scrollTo(0, (document.documentElement.scrollHeight - innerHeight) / 2));
	await settled(page);
}

/**
 * The rows in view must follow one another without gaps (none missing, none stacked) and, unless the end of the list
 * is in view (filled false), fill the view: no blank rows.
 */
function expectContiguous(shown, what, filled = true) {
	if (filled) {
		expect(shown.visibleRows, `${what}: the view is filled with rows (${shown.indexes})`)
			.toBeGreaterThanOrEqual(Math.floor(shown.viewHeight / shown.pitch) - 1);
	}
	shown.indexes.forEach((index, at) => {
		if (at > 0) {
			expect(index, `${what}: rows follow one another (${shown.indexes})`).toBe(shown.indexes[at - 1] + 1);
		}
	});
}

test.describe(`Graphs list of ${MILLION} named graphs`, () => {
	test('End shows the last named graph and then the default graph', async ({ page }) => {
		await openGraphs(page, MILLION);
		await page.keyboard.press('End');
		await settled(page);
		const end = await view(page);
		expect(end.lastWhole, 'the last named graph is wholly in view').toBe(MILLION - 1);
		expect(end.defaultInView, 'the default graph row is wholly in view').toBe(true);
		// The default graph row and the page's end take part of the view.
		expectContiguous(end, 'at the end', false);
	});

	test('the middle of the list shows the rows in the middle', async ({ page }) => {
		await openGraphs(page, MILLION);
		await toMiddle(page);
		const middle = await view(page);
		expect(middle.first, 'half way down the page shows graphs half way down the list')
			.toBeGreaterThan(MILLION * 0.48);
		expect(middle.first).toBeLessThan(MILLION * 0.52);
		expectContiguous(middle, 'in the middle');
	});

	test('a fast drag to the end stays at the end', async ({ page }) => {
		await openGraphs(page, MILLION);
		for (let step = 1; step <= 20; step++) {
			await page.evaluate(fraction => window.scrollTo(0,
				(document.documentElement.scrollHeight - innerHeight) * fraction), 0.5 + step / 40);
			await page.waitForTimeout(16);
		}
		await settled(page);
		const end = await view(page);
		expect(end.lastWhole, 'the last named graph is wholly in view').toBe(MILLION - 1);
		expect(end.defaultInView, 'the default graph row is wholly in view').toBe(true);
	});

	test('wheel steps move the rows as far as they scroll', async ({ page }) => {
		await openGraphs(page, MILLION);
		await toMiddle(page);
		await page.mouse.move(640, 500);
		const before = await view(page);
		for (let step = 0; step < 10; step++) {
			await page.mouse.wheel(0, 100);
			await page.waitForTimeout(20);
		}
		await settled(page);
		const after = await view(page);
		const expected = 1000 / before.pitch;
		expect(after.position - before.position,
			`10 wheel steps of 100 px should move about ${expected.toFixed(1)} rows of ${before.pitch} px`)
			.toBeGreaterThan(expected * 0.85);
		expect(after.position - before.position).toBeLessThan(expected * 1.15);
		expectContiguous(after, 'after the wheel');
	});

	test('PageDown, Space and Shift+Space page by about one view', async ({ page }) => {
		await openGraphs(page, MILLION);
		await toMiddle(page);
		for (const [key, direction] of [['PageDown', 1], ['Space', 1], ['Shift+Space', -1]]) {
			const before = await view(page);
			const oneView = before.viewHeight / before.pitch;
			await page.keyboard.press(key);
			await settled(page);
			const after = await view(page);
			const moved = (after.position - before.position) * direction;
			expect(moved, `${key} should move about one view (${oneView.toFixed(1)} rows), not many`)
				.toBeGreaterThan(oneView * 0.7);
			expect(moved).toBeLessThan(oneView * 1.05);
			expectContiguous(after, `after ${key}`);
		}
	});
});

// Chromium takes touch events (with native scrolling) through the DevTools protocol.
test.describe(`Graphs list of ${MILLION} named graphs on a touch screen`, () => {
	test.use({ hasTouch: true });
	test.skip(({ browserName }) => browserName !== 'chromium', 'touch gestures are synthesized through Chromium');

	test('a swipe moves the rows by the distance of the finger', async ({ page }) => {
		await openGraphs(page, MILLION);
		await toMiddle(page);
		const before = await view(page);
		await swipeUp(page, 640, 800, 300);
		await settled(page);
		const after = await view(page);
		const moved = (after.position - before.position) * before.pitch;
		// Chromium starts scrolling once the finger has moved its touch slop (15 px) and rounds a little.
		expect(moved, 'a 300 px swipe should move the rows about 300 px').toBeGreaterThan(250);
		expect(moved).toBeLessThan(400);
		await page.waitForTimeout(800);
		const later = await view(page);
		expect(Math.abs(later.position - after.position), 'the rows stay put once the swipe has settled')
			.toBeLessThan(0.05);
		expectContiguous(later, 'after the swipe');
	});
});

test('End shows the last of 20,000 named graphs and then the default graph', async ({ page }) => {
	await openGraphs(page, 20000);
	await page.keyboard.press('End');
	await settled(page);
	const end = await view(page);
	// Rows measured taller than estimated made the list longer once End had scrolled to what was its end.
	expect(end.lastWhole, 'the last named graph is wholly in view').toBe(19999);
	expect(end.defaultInView, 'the default graph row is wholly in view').toBe(true);
});

/**
 * Swipes a finger `distance` px up from (x, y) through the DevTools protocol's touch events, and holds it still before
 * lifting it so the swipe ends without a fling.
 */
async function swipeUp(page, x, y, distance) {
	const session = await page.context().newCDPSession(page);
	const touch = (type, points) => session.send('Input.dispatchTouchEvent', { type, touchPoints: points });
	await touch('touchStart', [{ x, y }]);
	for (let step = 1; step <= 15; step++) {
		await touch('touchMove', [{ x, y: y - distance * step / 15 }]);
		await page.waitForTimeout(16);
	}
	for (let still = 0; still < 6; still++) {
		await touch('touchMove', [{ x, y: y - distance }]);
		await page.waitForTimeout(30);
	}
	await touch('touchEnd', []);
	await session.detach();
}
